  const contentType = req.headers['content-type'];
  if (!contentType || !/^application\/json(?:\s*;|$)/i.test(contentType)) {
    fields.push({ field: 'body', message: 'Content-Type must be application/json.' });
  }
  const keyHeader = req.headers['idempotency-key'];
  const key = Array.isArray(keyHeader) ? keyHeader[0] : keyHeader;
  if (key !== undefined && !/^[A-Za-z0-9_-]{1,128}$/.test(key)) {
    fields.push({ field: 'Idempotency-Key', message: 'Must contain 1–128 letters, numbers, underscores, or hyphens.' });
  }
