const db = openDatabase();
let stopping = false;
for (const signal of ['SIGINT', 'SIGTERM'] as const) process.on(signal, () => { stopping = true; });

// A running row belongs to a worker that exited unexpectedly. Replay that same attempt from step zero.
db.exec(`BEGIN IMMEDIATE;
  UPDATE jobs SET status='queued', progress_completed=0, recovery=1, available_at=0,
