console.log('worker started');

async function runOne(): Promise<boolean> {
  db.exec('BEGIN IMMEDIATE');
  let row: any;
  try {
    row = db.prepare(`SELECT * FROM jobs WHERE status='queued' AND available_at <= ?
      ORDER BY created_at ASC, rowid ASC LIMIT 1`).get(Date.now());
    if (!row) { db.exec('COMMIT'); return false; }
    const attempts = row.attempts + (row.recovery ? 0 : 1);
    db.prepare(`UPDATE jobs SET status='running', attempts=?, progress_completed=0, recovery=0, updated_at=? WHERE id=? AND status='queued'`)
      .run(attempts, new Date().toISOString(), row.id);
    db.exec('COMMIT');
    row.attempts = attempts;
  } catch (e) { db.exec('ROLLBACK'); throw e; }

  if (row.attempts <= row.fail_attempts) {
    await sleep(100);
    const now = new Date().toISOString();
    if (row.attempts >= 3) {
      db.prepare(`UPDATE jobs SET status='failed', error='transient failure', result_output=NULL, progress_completed=0, updated_at=? WHERE id=? AND status='running'`).run(now, row.id);
    } else {
      db.prepare(`UPDATE jobs SET status='queued', error=NULL, result_output=NULL, progress_completed=0, available_at=?, updated_at=? WHERE id=? AND status='running'`).run(Date.now() + 500, now, row.id);
    }
    return true;
  }

  for (let completed = 1; completed <= row.steps; completed++) {
    await sleep(100);
    db.prepare(`UPDATE jobs SET progress_completed=?, updated_at=? WHERE id=? AND status='running'`)
      .run(completed, new Date().toISOString(), row.id);
  }
  db.prepare(`UPDATE jobs SET status='completed', result_output=?, error=NULL, updated_at=? WHERE id=? AND status='running'`)
    .run(String(row.input).toUpperCase(), new Date().toISOString(), row.id);
  return true;
}

try {
  while (!stopping) {
    const didWork = await runOne();
    if (!didWork) await sleep(100);
    heartbeat();
  }
} finally {
  clearInterval(heartbeatTimer);
  db.prepare('DELETE FROM worker_heartbeat WHERE id=1').run();
  db.close();
}
