  <h1>Job tracker</h1>
  <form data-testid="job-form" id="job-form">
    <label>Input
      <input data-testid="job-input" id="job-input" type="text" maxlength="1000">
    </label>
    <div class="numbers">
      <label>Steps
        <input data-testid="job-steps" id="job-steps" type="number" min="1" max="20" step="1" value="5">
      </label>
      <label>Fail attempts
        <input data-testid="job-fail-attempts" id="job-fail-attempts" type="number" min="0" max="5" step="1" value="0">
      </label>
    </div>
    <div data-testid="form-error" id="form-error" role="alert" aria-live="polite"></div>
    <button data-testid="job-submit" type="submit">Submit job</button>
  </form>

  <h2>Jobs</h2>
  <ul data-testid="job-list" id="job-list"></ul>
  <script>
    const form = document.querySelector('[data-testid="job-form"]');
    const errorBox = document.querySelector('[data-testid="form-error"]');
    const list = document.querySelector('[data-testid="job-list"]');
    const escapeText = value => String(value ?? '');
    function render(jobs) {
      list.replaceChildren(...jobs.map(job => {
        const item = document.createElement('li');
        item.className = 'job'; item.dataset.testid = 'job-item'; item.dataset.jobId = job.id;
        const title = document.createElement('h3'); title.textContent = job.input;
        const status = document.createElement('p'); status.append('Status: ');
        const statusValue = document.createElement('span'); statusValue.dataset.testid = 'job-status'; statusValue.textContent = job.status; status.append(statusValue);
        const progress = document.createElement('p'); progress.append('Progress: ');
        const progressValue = document.createElement('span'); progressValue.dataset.testid = 'job-progress'; progressValue.textContent = `${job.progress.completed}/${job.progress.total}`; progress.append(progressValue);
        const result = document.createElement('p'); result.className = 'result'; result.dataset.testid = 'job-result';
        result.textContent = job.status === 'completed' ? escapeText(job.result?.output) : job.status === 'failed' ? escapeText(job.error) : '';
        item.append(title, status, progress, result); return item;
      }));
    }
    async function refresh() {
      try { const response = await fetch('/api/jobs'); if (response.ok) render((await response.json()).jobs); }
      catch { /* keep the last displayed state while the server is unavailable */ }
    }
    form.addEventListener('submit', async event => {
      event.preventDefault(); errorBox.textContent = '';
      const input = document.querySelector('[data-testid="job-input"]').value;
      const stepsValue = document.querySelector('[data-testid="job-steps"]').value;
      const failValue = document.querySelector('[data-testid="job-fail-attempts"]').value;
      const payload = { input, steps: stepsValue === '' ? '' : Number(stepsValue), failAttempts: failValue === '' ? '' : Number(failValue) };
      try {
        const response = await fetch('/api/jobs', { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify(payload) });
        const data = await response.json();
        if (!response.ok) {
          const details = data.error?.fields?.map(field => `${field.field}: ${field.message}`) ?? [data.error?.message ?? 'Submission failed.'];
          errorBox.textContent = details.join(' ');
        } else { form.reset(); document.querySelector('[data-testid="job-steps"]').value = '5'; document.querySelector('[data-testid="job-fail-attempts"]').value = '0'; await refresh(); }
      } catch { errorBox.textContent = 'Unable to submit the job. Please try again.'; }
    });
    refresh(); setInterval(refresh, 1000);
  </script>
